//! Button and textarea label lists use native association authority.
use super::*;
#[test]
fn button_textarea_labels_author_overrides_saved_getters_and_live_callbacks(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var tag of ['button','textarea']){var source=document.getElementById(tag==='button'?'button':'text'),prototype=tag==='button'?HTMLButtonElement.prototype:HTMLTextAreaElement.prototype,descriptor=Object.getOwnPropertyDescriptor(prototype,'labels'),labels=source.labels,first=labels[0],second=labels[1],calls=0;Object.defineProperty(first,'control',{get:function(){calls++;return null;},configurable:true});if(labels.length!==2||labels[0]!==first||calls)throw 'native association ignores author control';Object.defineProperty(source,'labels',{value:'own',writable:true,configurable:true});source.labels='updated';if(source.labels!=='updated'||descriptor.get.call(source)!==labels)throw 'own shadow and saved native identity';delete source.labels;Object.defineProperty(prototype,'labels',{get:function(){return 'prototype';},configurable:true});if(source.labels!=='prototype'||descriptor.get.call(source)!==labels)throw 'prototype shadow';delete prototype.labels;if(source.labels!==undefined||descriptor.get.call(source)!==labels)throw 'deleted descriptor';Object.defineProperty(prototype,'labels',descriptor);var count=0;for(var key in source)if(key==='labels')count++;if(count!==1||source.labels!==labels)throw 'restored inherited native descriptor';var seen=[];labels.forEach(function(label,index,list){if(list!==labels)throw 'actual callback list';seen.push(label);if(index===0)second.remove();});if(seen.length!==1||seen[0]!==first||labels.length!==1)throw 'callback reads current membership';}"#);}
#[test]
fn button_textarea_labels_independent_clone_import_adoption_and_no_main_slots(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source'),target=document.implementation.createHTMLDocument('target');for(var tag of ['button','textarea']){var root=owner.createElement('div'),label=owner.createElement('label'),control=owner.createElement(tag);control.id=tag+'\ud800';label.htmlFor=control.id;root.appendChild(label);root.appendChild(control);var labels=control.labels,clone=root.cloneNode(true),copies=clone.lastChild.labels;if(labels.length!==1||copies===labels||copies.length!==1||copies[0]!==clone.firstChild)throw 'independent clone';target.adoptNode(root);target.body.appendChild(root);if(control.ownerDocument!==target||control.labels!==labels||labels[0]!==label)throw 'actual adopted source';var imported=document.importNode(root,true),field=imported.lastChild,list=field.labels;document.getElementById('mount').appendChild(imported);if(list===labels||field.labels!==list||list.length!==1||list[0]!==imported.firstChild||list[0]===label)throw 'actual independent main import';label.htmlFor='absent';if(labels.length||copies.length!==1||list.length!==1)throw 'independent native associations';}"#);let slots=d.nodes.len();p.state.node_limit=slots;p.begin_job();run(&mut d,&mut f,&mut p,r#"for(var tag of ['button','textarea']){var label=owner.createElement('label'),control=owner.createElement(tag);label.appendChild(control);var list=control.labels;if(list.length!==1||list[0]!==label||control.labels!==list)throw 'inert source without main slots';}"#);assert_eq!(d.nodes.len(),slots);}
#[test]
fn button_textarea_labels_creation_and_refresh_limits_preserve_records_and_recover(){for (id,method) in [("button","\0HTMLButtonElement.get.labels"),("text","\0HTMLTextAreaElement.get.labels")]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some(id)).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.node_lists.len(),p.state.retained,p.state.dom_commits);let retained=p.state.retained_limit;let arenas=p.state.limits.test_entry_arenas;let quota=p.state.limits.host.node_lists;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>{p.state.limits.test_entry_arenas=true;p.state.limits.host.node_lists=p.state.node_lists.len();},3=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_control_labels_get(node_handle(node),method).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.node_lists.len(),p.state.retained,p.state.dom_commits),state);p.state.retained_limit=retained;p.state.limits.test_entry_arenas=arenas;p.state.limits.host.node_lists=quota;p.state.execution_deadline=None;p.begin_job();let list=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_control_labels_get(node_handle(node),method).unwrap();let after=(p.state.node_lists.len(),p.state.retained,p.state.dom_commits);assert_eq!(after.0,state.0+1);for refresh in 0..4{p.begin_job();match refresh{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())};let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_labels_list_nodes(node_handle(node)).unwrap_err();assert!(error.contains("work")||error.contains("allowance")||error.contains("bound")||error.contains("limit"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.node_lists.len(),p.state.retained,p.state.dom_commits),after);p.state.retained_limit=retained;p.state.execution_deadline=None;}p.begin_job();let recovered=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.html_control_labels_get(node_handle(node),method).unwrap();assert_eq!(format!("{list:?}"),format!("{recovered:?}"));assert_eq!(Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_labels_list_nodes(node_handle(node)).unwrap().len(),2);}}}
#[test]
fn button_textarea_labels_captured_child_getters_retain_origin_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var button=document.getElementById('button'),text=document.getElementById('text'),buttons=button.labels,texts=text.labels,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var buttonGet=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLButtonElement.prototype,'labels').get,textGet=Object.getOwnPropertyDescriptor(frame.contentWindow.HTMLTextAreaElement.prototype,'labels').get;if(buttonGet.call(button)!==buttons||textGet.call(text)!==texts)throw 'same origin captured getter identity';"#);let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.set_location(&crate::navigation::address("https://other-label-lists.test/",&crate::navigation::Location::home()).unwrap());for source in ["buttonGet.call(button);","textGet.call(text);"]{p.begin_job();let error=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);}p.set_location(&crate::navigation::address("https://control-label-lists.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(buttonGet.call(button)!==buttons||textGet.call(text)!==texts||buttons.length!==2||texts.length!==2)throw 'fresh captured getter recovery';");}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><label id=first for=button>First</label><label id=buttonwrap>Button<button id=button>Go</button></label><label id=textwrap>Text<textarea id=text>seed</textarea></label><label id=last for=text>Last</label><div id=mount></div></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://control-label-lists.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn button_textarea_labels_canonical_brands_and_stable_native_collections(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var button=document.getElementById('button'),text=document.getElementById('text'),sources=[button,text],prototypes=[HTMLButtonElement.prototype,HTMLTextAreaElement.prototype];for(var at=0;at<2;at++){var source=sources[at],d=Object.getOwnPropertyDescriptor(prototypes[at],'labels');if(!d||typeof d.get!=='function'||d.set!==undefined||!d.enumerable||!d.configurable||d.get.name!=='get labels'||d.get.length!==0||Object.hasOwn(source,'labels'))throw 'canonical labels descriptor';var labels=source.labels;if(labels!==source.labels||labels!==d.get.call(source)||Object.getPrototypeOf(labels)!==NodeList.prototype||labels.length!==2||labels.item(2)!==null||Object.keys(labels).join(',')!=='0,1'||Array.from(labels)[1]!==labels[1])throw 'actual SameObject native collection';source.labels='ignored';if(source.labels!==labels)throw 'readonly sloppy';var caught=false;try{(function(){'use strict';source.labels=null;})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'readonly strict';for(var bad of [{},Object.create(prototypes[at]),sources[1-at],document.createElement('input'),document.createElementNS('urn:foreign',at?'textarea':'button')]){caught=false;try{d.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'distinct genuine labels brands';}}"#);}
#[test]
fn button_textarea_labels_exact_association_and_live_native_order(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var button=document.getElementById('button'),text=document.getElementById('text'),first=document.getElementById('first'),last=document.getElementById('last'),buttons=button.labels,texts=text.labels;button.id='A\ud800z';first.htmlFor='A\ud800z';last.htmlFor='A�z';if(buttons.length!==2||buttons[0]!==first||texts.length!==1)throw 'exact code-unit associations';var blocker=document.createElement('div');blocker.id='A\ud800z';document.body.insertBefore(blocker,first);if(buttons.length!==1||buttons[0]!==document.getElementById('buttonwrap'))throw 'first nonlabelable ID blocks';blocker.remove();first.remove();document.getElementById('mount').appendChild(first);if(buttons.length!==2||buttons[1]!==first||button.labels!==buttons)throw 'actual live tree order';last.htmlFor='text';if(texts.length!==2||texts[1]!==last||text.labels!==texts)throw 'independent textarea recovery';"#);}
#[test]
fn button_textarea_labels_inert_disconnected_roots_and_type_content(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.implementation.createHTMLDocument('source');for(var tag of ['button','textarea']){var root=owner.createElement('div'),label=owner.createElement('label'),control=owner.createElement(tag),outside=owner.createElement('label');control.id=tag;label.htmlFor=tag;outside.htmlFor=tag;root.appendChild(label);root.appendChild(control);owner.body.appendChild(outside);var labels=control.labels;if(labels.length!==1||labels[0]!==label||control.labels!==labels)throw 'actual detached root';control.setAttribute('type','hidden');if(control.labels!==labels||labels.length!==1)throw 'hidden content only affects input';owner.body.appendChild(root);if(labels.length!==2||labels[0]!==outside||labels[1]!==label)throw 'connected native tree';owner.body.removeChild(root);if(labels.length!==1||labels[0]!==label)throw 'disconnected live recovery';}"#);}
